  function parseGLB(ab) {
    const view = new DataView(ab);
    if (view.getUint32(0, true) !== 0x46546C67) {
      throw new Error('Not a valid GLB file');
    }
    const version = view.getUint32(4, true);
    if (version !== 2) {
      throw new Error('Unsupported GLB version');
    }
    const length = view.getUint32(8, true);
    if (length !== ab.byteLength) {
      throw new Error('GLB length mismatch');
    }

    const chunks = [];
    let offset = 12;
    while (offset < length) {
      const chunkLength = view.getUint32(offset, true);
      const chunkType = view.getUint32(offset + 4, true);
      const chunkData = new Uint8Array(ab, offset + 8, chunkLength);
      chunks.push({ type: chunkType, data: chunkData });
      offset += 8 + chunkLength;
      // Pad to 4-byte boundary
