window.Assets = {
  instance: new Map(),

  parseGLB: function(base64Name) {
    try {
      const binaryString = atob(window.ASSETS[base64Name]);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      const view = new DataView(bytes.buffer);

      // Check GLB header
      if (view.getUint32(0, true) !== 0x46546C67) {
        throw new Error('Invalid GLB header');
      }

      const length = view.getUint32(4, true);
      if (length !== bytes.length) {
        throw new Error('GLB length mismatch');
      }

      // Parse chunks
      let chunkOffset = 12;
      let jsonChunk = null;
      let binaryChunk = null;

      while (chunkOffset < bytes.length) {
        const chunkLength = view.getUint32(chunkOffset, true);
        const chunkType = view.getUint32(chunkOffset + 4, true);

        if (chunkType === 0x4E4F534A) { // JSON chunk
          const jsonString = new TextDecoder().decode(bytes.subarray(chunkOffset + 8, chunkOffset + 8 + chunkLength));
          jsonChunk = JSON.parse(jsonString);
        } else if (chunkType === 0x004E4942) { // BIN chunk
          binaryChunk = bytes.subarray(chunkOffset + 8, chunkOffset + 8 + chunkLength);
        }

        chunkOffset += 8 + chunkLength;
        // Align to 4-byte boundary
        chunkOffset = (chunkOffset + 3) & ~3;
      }

      if (!jsonChunk) throw new Error('No JSON chunk found');

      const gltf = jsonChunk;
      const accessors = gltf.accessors || [];
      const buffers = gltf.buffers || [];
      const bufferViews = gltf.bufferViews || [];
      const meshes = gltf.meshes || [];
      const materials = gltf.materials || [];

      // Create buffer views
      const bufferData = new Map();
      for (let i = 0; i < bufferViews.length; i++) {
        const bufferView = bufferViews[i];
        const buffer = bufferView.buffer;
        const offset = bufferView.byteOffset || 0;
        const length = bufferView.byteLength;
        bufferData.set(i, binaryChunk.subarray(offset, offset + length));
      }

      // Create meshes
      const group = new THREE.Group();

      for (let i = 0; i < meshes.length; i++) {
        const mesh = meshes[i];
        for (let j = 0; j < mesh.primitives.length; j++) {
          const primitive = mesh.primitives[j];
          const attributes = primitive.attributes;
          const indices = primitive.indices;

          // Prepare geometry data
          const geometry = new THREE.BufferGeometry();

          // Positions
          if (attributes.POSITION !== undefined) {
            const accessor = accessors[attributes.POSITION];
            const bufferView = bufferData.get(accessor.bufferView);

            if (bufferView) {
              const componentType = accessor.componentType;
              const count = accessor.count;
              const type = accessor.type;
              const byteStride = bufferViews[accessor.bufferView].byteStride;

              let array;
              if (componentType === 5126) { // FLOAT
                array = new Float32Array(count * 3);
                for (let k = 0; k < count * 3; k++) {
                  array[k] = new DataView(bufferView.buffer, bufferView.byteOffset + k * 4).getFloat32(k * 4, true);
                }
              } else if (componentType === 5123) { // UNSIGNED_SHORT
                array = new Uint16Array(count * 3);
                for (let k = 0; k < count * 3; k++) {
                  array[k] = new DataView(bufferView.buffer, bufferView.byteOffset + k * 2).getUint16(k * 2, true);
                }
              }

              if (array) {
                geometry.setAttribute('position', new THREE.BufferAttribute(array, 3));
              }
            }
          }

          // Normals
          if (attributes.NORMAL !== undefined) {
            const accessor = accessors[attributes.NORMAL];
            const bufferView = bufferData.get(accessor.bufferView);

            if (bufferView) {
              const componentType = accessor.componentType;
              const count = accessor.count;
              const byteStride = bufferViews[accessor.bufferView].byteStride;

              let array;
              if (componentType === 5126) { // FLOAT
                array = new Float32Array(count * 3);
                for (let k = 0; k < count * 3; k++) {
                  array[k] = new DataView(bufferView.buffer, bufferView.byteOffset + k * 4).getFloat32(k * 4, true);
                }
              } else if (componentType === 5123) { // UNSIGNED_SHORT
                array = new Uint16Array(count * 3);
                for (let k = 0; k < count * 3; k++) {
                  array[k] = new DataView(bufferView.buffer, bufferView.byteOffset + k * 2).getUint16(k * 2, true);
                }
              }

              if (array) {
                geometry.setAttribute('normal', new THREE.BufferAttribute(array, 3));
              }
            }
          }

          // Indices
          if (indices !== undefined) {
            const accessor = accessors[indices];
            const bufferView = bufferData.get(accessor.bufferView);

            if (bufferView) {
              const componentType = accessor.componentType;
              const count = accessor.count;

              let array;
              if (componentType === 5123) { // UNSIGNED_SHORT
                array = new Uint16Array(count);
                for (let k = 0; k < count; k++) {
                  array[k] = new DataView(bufferView.buffer, bufferView.byteOffset + k * 2).getUint16(k * 2, true);
                }
              }

              if (array) {
                geometry.setIndex(new THREE.BufferAttribute(array, 1));
              }
            }
          }

          // Material
          let material = new THREE.MeshLambertMaterial({color: 0x888888});

          if (primitive.material !== undefined && materials[primitive.material]) {
            const gltfMaterial = materials[primitive.material];

            if (gltfMaterial.pbrMetallicRoughness && gltfMaterial.pbrMetallicRoughness.baseColorFactor) {
              const color = gltfMaterial.pbrMetallicRoughness.baseColorFactor;
              material = new THREE.MeshLambertMaterial({
                color: new THREE.Color(color[0], color[1], color[2]),
                transparent: color[3] < 1.0
              });
            } else {
              material = new THREE.MeshLambertMaterial({color: 0x888888});
            }
          }

          // Create mesh
          const meshInstance = new THREE.Mesh(geometry, material);
          group.add(meshInstance);
        }
      }

      return group;
    } catch (e) {
      console.warn(`Failed to parse GLB asset '${base64Name}':`, e);
      return new THREE.Mesh(
        new THREE.BoxGeometry(1, 1, 1),
        new THREE.MeshLambertMaterial({color: 0xff0000})
      );
    }
  },

  get: function(name) {
    if (!this.instance.has(name)) {
      this.instance.set(name, this.parseGLB(name));
    }
    return this.instance.get(name);
  }
};
