window.Game = {
  init: function(scene, camera) {
    this.scene = scene;
    this.camera = camera;
    this.player = {
      position: new THREE.Vector3(0, 1.7, 0),
      velocity: new THREE.Vector3(),
      onGround: false,
      sprinting: false,
      weapon: null,
      recoil: { amount: 0, timer: 0 },
      reload: { active: false, timer: 0 }
    };

    const gun = window.Assets.get('revolver');
    const loader = new THREE.GLTFLoader();
    const gunData = atob(gun.split(',')[1]);
    const blob = new Blob([gunData], { type: 'application/octet-stream' });
    const url = URL.createObjectURL(blob);

    loader.load(url, (gltf) => {
      this.player.weapon = gltf.scene;
      this.player.weapon.scale.setScalar(0.3);
      this.player.weapon.position.set(0.25, -0.22, -0.5);
      this.camera.add(this.player.weapon);
      URL.revokeObjectURL(url);
    });

    this.controls = new THREE.PointerLockControls(camera, document.body);
    this.pointerLockElement = document.getElementById('lock');
    this.pointerLockElement.addEventListener('click', () => {
      this.controls.lock();
    });

    window.addEventListener('keydown', (e) => {
      if (e.key === 'r' || e.key === 'R') {
        this.player.reload.active = true;
        this.player.reload.timer = 1600;
        window.Sfx.reload();
      }
    });
  },

  update: function(dt, input) {
    if (!this.controls.isLocked) return;

    const moveSpeed = this.player.sprinting ? 12 : 6;
    const moveVector = new THREE.Vector3();
    if (input.forward) moveVector.z -= 1;
    if (input.backward) moveVector.z += 1;
    if (input.left) moveVector.x -= 1;
    if (input.right) moveVector.x += 1;

    moveVector.normalize().multiplyScalar(moveSpeed * dt);

    const cameraDirection = new THREE.Vector3();
    this.camera.getWorldDirection(cameraDirection);
    cameraDirection.y = 0;
    cameraDirection.normalize();

    const cameraRight = new THREE.Vector3();
    cameraRight.crossVectors(new THREE.Vector3(0, 1, 0), cameraDirection).normalize();

    const moveX = cameraRight.clone().multiplyScalar(moveVector.x);
    const moveZ = cameraDirection.clone().multiplyScalar(moveVector.z);
    const move = moveX.add(moveZ);

    // Update position with collision detection
    this.player.position.add(move);
    this.player.position.y = 1.7;

    if (window.World.colliders) {
      for (const collider of window.World.colliders) {
        const distance = this.player.position.distanceTo(collider.position);
        if (distance < 0.5 + collider.radius) {
          const direction = this.player.position.clone().sub(collider.position).normalize();
          this.player.position.copy(collider.position).add(direction.multiplyScalar(0.5 + collider.radius));
        }
      }
    }

    // Apply recoil animation
    if (this.player.recoil.timer > 0) {
      this.player.recoil.timer -= dt * 1000;
      this.player.weapon.rotation.x = this.player.recoil.amount * (this.player.recoil.timer / 120);
    } else if (this.player.recoil.amount > 0) {
      this.player.recoil.amount = 0;
    }

    // Update reload animation
    if (this.player.reload.active) {
      this.player.reload.timer -= dt * 1000;
      if (this.player.reload.timer <= 0) {
        this.player.reload.active = false;
        this.player.reload.timer = 0;
        // Simulate cylinder rolling out when reload completes
        if (this.player.weapon.children[0]) {
          this.player.weapon.children[0].rotation.z = 0;
          this.player.weapon.children[0].position.y = 0;
        }
      } else if (this.player.reload.timer < 800) {
        this.player.weapon.rotation.z = THREE.MathUtils.lerp(this.player.weapon.rotation.z, 0.5, 0.1);
        this.player.weapon.position.y = THREE.MathUtils.lerp(this.player.weapon.position.y, -0.5, 0.05);
      }
    }

    // Auto reload with burst weapon
    if (this.player.reload.active === false) {
      this.player.fireCooldown = this.player.fireCooldown || 0;
      this.player.fireCooldown -= dt * 1000;
      if (input.fire && this.player.fireCooldown <= 0) {
        this.player.fire();
        this.player.fireCooldown = 350; // Shots per second
      }
    }

    // Update viewmodel position and rotation
    if (this.player.weapon) {
      this.player.weapon.position.x = 0.25;
      this.player.weapon.position.y = -0.22;
      this.player.weapon.position.z = -0.5;
      this.player.weapon.rotation.x = this.player.recoil.amount * (this.player.recoil.timer / 120);
    }

    // Update HUD ammo
    if (window.HUD) window.HUD.updateAmmo(16); // Dummy count
  },

  fire: function() {
    if (this.player.reload.active || !this.player.weapon) return;

    // Apply recoil
    this.player.recoil.amount = 0.12;
    this.player.recoil.timer = 120;

    // Apply weapon kick
    this.player.weapon.rotation.x = 0.12;
    this.player.weapon.position.z += 0.12;

    // Send raycast
    const raycaster = new THREE.Raycaster(this.camera.position, this.camera.getWorldDirection(new THREE.Vector3()));
    const enemies = window.Enemies.rayTargets();
    const targets = raycaster.intersectObjects(enemies);

    if (targets.length > 0) {
      return targets[0].object.userData.hit;
    }

    return null;
  },

  rayTargets: function() {
    return window.Enemies.rayTargets();
  }
};

window.Player = {
  aimRay: function() {
    const raycaster = new THREE.Raycaster(this.camera.position, this.camera.getWorldDirection(new THREE.Vector3()));
    return raycaster;
  }
};
