            shield.scale.set(0.7, 0.7, 0.7);
            shield.position.set(-0.6, 0.2, 0);
            shield.rotation.z = Math.PI / 2;
            this.mesh.add(shield);
            this.shield = shield;

            // Sword
            const sword = loader.parse(window.Assets.get('sword')).scene;
            sword.scale.set(0.6, 0.6, 0.6);
            sword.position.set(0.6, 0, 0);
            sword.rotation.z = -Math.PI / 2;
            this.mesh.add(sword);
            this.sword = sword;

            // Movement and state
            this.speed = 2.2;
            this.isAttacking = false;
            this.isStrafing = false;
            this.strafeTime = 0;
            this.attackTime = 0;
            this.swingCooldown = 0;
            this.state = 'walking';
            this.lastStrafe = 0;
            this.lookAt = new THREE.Vector3();
            this.shieldUp = true;
        }

        update(dt, playerPos, waveNumber) {
            this.swingCooldown -= dt;
            const speed = waveNumber % 2 === 0 ? 3.4 : 2.2;
            this.attackTime += dt;

            if (this.isAttacking) {
                if (this.attackTime > 0.8) {
                    this.state = 'attack';
                }
                if (this.attackTime > 1.6) {
                    this.isAttacking = false;
                    this.attackTime = 0;
                    this.state = 'walking';
                    this.shieldUp = true;
                }
            } else {
                // Strafing logic
                if (this.lastStrafe < 2 || this.lastStrafe > 4) {
                    this.isStrafing = true;
                    this.strafeTime += dt;
                    if (this.strafeTime > 1) {
                        this.isStrafing = false;
                        this.strafeTime = 0;
                        this.lastStrafe = 0;
                    }
                } else {
                    this.lastStrafe += dt;
                }

                const dist = this.mesh.position.distanceTo(playerPos);
                if (dist < 2.4) {
                    this.isAttacking = true;
                    this.attackTime = 0;
                    this.state = 'telegraph';
                } else {
                    this.state = 'walking';
                }
            }

            // Look at the player
            this.lookAt.copy(playerPos).sub(this.mesh.position).normalize();
            this.mesh.lookAt(playerPos);

            // Movement
            const moveDir = this.lookAt.clone().multiplyScalar(speed * dt);
            this.mesh.position.add(moveDir);

            // Shield animation during walk/strafe
            if (this.state === 'walking' || this.isStrafing) {
                this.shield.rotation.x = 0.7;
                this.sword.rotation.x = 0.3;
            } else if (this.state === 'telegraph') {
                this.shield.rotation.x = 1.5;
                this.sword.rotation.x = 1.0;
            } else if (this.state === 'attack') {
                this.shield.rotation.x = 1.5;
                this.sword.rotation.x = -0.8;
            }

            // Striking logic
            if (this.state === 'attack' && this.attackTime > 1.2) {
                this.swing();
            }
        }

        swing() {
            window.Sfx.swing();
            const angle = this.mesh.rotation.y;
            const halfArc = Math.PI * 110 / 180;
            const from = this.mesh.position.clone();
            const to = new THREE.Vector3(
                from.x + Math.sin(angle) * 2.6,
                from.y,
                from.z + Math.cos(angle) * 2.6
            );

            // Raycast to detect hit
            const raycaster = new THREE.Raycaster(from, to.clone().sub(from).normalize());
            const intersects = raycaster.intersectObjects(window.Enemies.rayTargets());
            for (const hit of intersects) {
                if (hit.object.userData.hp !== undefined) {
                    window.Player.hurt(15, hit.face.normal);
                }
